    2: { id: 2, name: 'Bob' },
  };

  const user = users[parseInt(id, 10)];

  if (!user) {
    throw new NotFoundError('User not found');
  }

  // Never expose sensitive fields
  const safeUser = {
    id: user.id,
    name: user.name,
  };

  res.json(safeUser);
}));

// Example: POST endpoint with validation
app.post('/users',
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be 1-100 characters')
      .escape(),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Valid email required')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email too long'),
  ],
  asyncHandler(async (req, res, next) => {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      throw new ValidationError(errors.array().map(e => e.msg).join(', '));
    }

    const { name, email } = req.body;

    // Additional sanitization
    const sanitizedUser = {
      name: sanitizeString(name),
      email: email.toLowerCase(),
    };

    // In production: save to database

    res.status(201).json({ 
      message: 'User created successfully',
      user: sanitizedUser 
    });
  })
);

// 404 handler for undefined routes
app.use((req, res, next) => {
  next(new NotFoundError(`Cannot ${req.method} ${req.path}`));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error details (use proper logging library in production)
  console.error({
    timestamp: new Date().toISOString(),
    method: req.method,
    path: req.path,
    ip: req.ip,
    error: err.message,
    stack: err.isOperational ? undefined : err.stack,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Don't expose internal errors to clients
  const message = err.isOperational ? err.message : 'Internal server error';

  res.status(statusCode).json({
    error: message,
    // Include stack trace only in development
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

const server = app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  // Close server gracefully
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

