// Improved application with security best practices
// Includes: input validation, error handling, security headers, rate limiting

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security headers using helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      scriptSrc: ["'self'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: 'same-origin' },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  noSniff: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  xssFilter: true,
}));

// 2. Rate limiting to prevent DoS and brute-force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  // Use X-Forwarded-For header if behind a proxy
  trustProxy: process.env.NODE_ENV === 'production',
});
app.use(limiter);

// 3. Stricter rate limit for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // Limit each IP to 5 requests per hour
  message: { error: 'Too many attempts, please try again later.' },
});

// 4. Request body parsing with size limits
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// 5. Request logging for audit trail
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('User-Agent'),
    });
  });

  next();
});

// ============================================
// INPUT VALIDATION UTILITIES
// ============================================

// Custom validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

// Sanitization helper to prevent XSS
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .replace(/[<>]/g, '') // Remove potential HTML tags
    .trim();
};

// ============================================
// ERROR HANDLING
// ============================================

// Custom error classes
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message) {
    super(message, 400);
    this.name = 'ValidationError';
  }
}

class NotFoundError extends AppError {
  constructor(message = 'Resource not found') {
    super(message, 404);
    this.name = 'NotFoundError';
  }
}

// Async handler wrapper to catch errors in async routes
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================
// MOCK DATA (replace with real database)
// ============================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// Filter sensitive fields before sending response
const filterUserData = (user) => ({
  id: user.id,
  name: user.name,
  // Only expose email to authorized requests in real apps
  // email: user.email, 
});

// ============================================
// ROUTES
// ============================================

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0',
  });
});

// Get all users with query validation
app.get('/users',
  [
    query('page')
      .optional()
      .isInt({ min: 1, max: 1000 })
      .withMessage('Page must be between 1 and 1000'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100'),
    query('search')
      .optional()
      .isLength({ max: 100 })
      .withMessage('Search query too long')
      .trim()
      .escape(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { page = 1, limit = 10, search } = req.query;

    let filteredUsers = users;

    // Safe search with sanitized input
    if (search) {
      const sanitizedSearch = sanitizeInput(search).toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(sanitizedSearch)
      );
    }

    // Pagination with safe defaults
    const pageNum = Math.max(1, parseInt(page, 10) || 1);
    const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10) || 10));
    const startIndex = (pageNum - 1) * limitNum;

    const paginatedUsers = filteredUsers
      .slice(startIndex, startIndex + limitNum)
      .map(filterUserData);

    res.json({
      users: paginatedUsers,
      pagination: {
        page: pageNum,
        limit: limitNum,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limitNum),
      },
    });
  })
);

// Get single user by ID with param validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1, max: 2147483647 })
      .withMessage('Invalid user ID format'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const userId = parseInt(req.params.id, 10);

    const user = users.find(u => u.id === userId);

    if (!user) {
      throw new NotFoundError(`User with ID ${userId} not found`);
    }

    res.json(filterUserData(user));
  })
);

// Example POST route with body validation
app.post('/users',
  authLimiter, // Stricter rate limit for creation
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters')
      .escape(),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 255 })
      .withMessage('Email too long'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // Check for duplicate email
    if (users.some(u => u.email.toLowerCase() === email.toLowerCase())) {
      throw new ValidationError('Email already in use');
    }

    // In a real app, hash sensitive data and validate before saving
    const newUser = {
      id: users.length + 1,
      name: sanitizeInput(name),
      email: email.toLowerCase(),
    };

    users.push(newUser);

    res.status(201).json({
      message: 'User created successfully',
      user: filterUserData(newUser),
    });
  })
);

// ============================================
// 404 HANDLER
// ============================================

app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} does not exist`,
  });
});

// ============================================
// GLOBAL ERROR HANDLER
// ============================================

app.use((err, req, res, next) => {
  // Log error details (hide in production)
  console.error({
    timestamp: new Date().toISOString(),
    error: {
      name: err.name,
      message: err.message,
      stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    },
    request: {
      method: req.method,
      path: req.path,
      ip: req.ip,
    },
  });

  // Operational errors: safe to send details to client
  if (err.isOperational) {
    return res.status(err.statusCode || 500).json({
      error: err.name || 'Error',
      message: err.message,
    });
  }

  // Programming errors: don't leak details
  res.status(500).json({
    error: 'Internal Server Error',
    message: process.env.NODE_ENV === 'production' 
      ? 'An unexpected error occurred' 
      : err.message,
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';

// Only start server if this file is run directly (not imported)
if (require.main === module) {
  app.listen(PORT, HOST, () => {
    console.log(`Server running on ${HOST}:${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

