const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');

const app = express();

// Security middleware - should be added early
app.use(helmet()); // Adds various HTTP headers for security

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON bodies with size limit
app.use(express.json({ limit: '10kb' })); // Limit body size to prevent payload attacks

// Input validation middleware factory
const validateInput = (validations) => {
  return async (req, res, next) => {
    try {
      await Promise.all(validations.map(validation => validation.run(req)));

      const errors = validationResult(req);
      if (errors.isEmpty()) {
        return next();
      }

      return res.status(400).json({ 
        error: 'Validation failed', 
        details: errors.array() 
      });
    } catch (error) {
      next(error);
    }
  };
};

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (error) {
    res.status(500).json({ error: 'Health check failed' });
  }
});

// Users endpoint - returns static user data
app.get('/users', (req, res) => {
  try {
    // In a real app, this would query a database with proper sanitization
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Failed to retrieve users' });
  }
});

// Example POST endpoint with proper validation
app.post('/users', 
  validateInput([
    body('name')
      .trim()
      .escape() // Sanitize against XSS
      .notEmpty().withMessage('Name is required')
      .isLength({ max: 100 }).withMessage('Name must be 100 characters or less'),
    body('email')
      .trim()
      .normalizeEmail()
      .isEmail().withMessage('Valid email is required')
      .isLength({ max: 255 }).withMessage('Email must be 255 characters or less'),
  ]),
  (req, res) => {
    try {
      // Input is now validated and sanitized
      const { name, email } = req.body;

      // Simulated user creation
      const newUser = { 
        id: Date.now(), // In production, use proper ID generation
        name, 
        email 
      };

      res.status(201).json(newUser);
    } catch (error) {
      console.error('Error creating user:', error);
      res.status(500).json({ error: 'Failed to create user' });
    }
  }
);

// 404 handler for undefined routes
app.use((req, res, next) => {
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error('Unhandled error:', err);

  // Don't expose internal errors to clients
  const status = err.status || err.statusCode || 500;
  const message = status === 500 
    ? 'Internal server error' 
    : err.message || 'An error occurred';

  res.status(status).json({ 
    error: message,
    // Only include stack trace in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// Graceful server startup
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

